uint64_t result = 0;
int shift = 0;
const char* start = p;
do {
    if (p >= limit) return nullptr;
    uint8_t byte = *(reinterpret_cast<const uint8_t*>(p));
    p++;
    if (shift < 64) {
        result |= (byte & 0x7F) << shift;
        shift += 7;
    } else {
        return nullptr; // overflow protection
    }
} while (start != p && (reinterpret_cast<const uint8_t*>(p) - 1 < limit));
*value = result;
return p;

